#!/bin/bash
# batch C1: generated by scripts/make_batch.py from tracks/kb/claims_tracks/decisions/C1.tsv; do not edit by hand
cd /data/haiyangw/nrpic/wt/kb || exit 2
fail=0
test -n "${NRPIC_RUN_DIR:-}" || { echo 'not inside nrpic-run'; exit 2; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py snapshot tracks/kb/claims_tracks/decisions/C1.tsv > "$NRPIC_RUN_DIR/before.json" || fail=1
/usr/bin/python3 -I kb/bin/kb claim verify 257 --by kb-claims_tracks --evidence 'gr-qc/0601112v1 L694 prints Z_c = 1/sqrt(alpha(0)) - 1. With the metric of L231 (g_tt = -(alpha^2 + a^2 beta^2), beta = 0 at the centre of a static cluster) the central redshift is 1/alpha(0) - 1 [my derivation], so the printed form is the defect the track names; consistent with C'"'"'s table check (claim 614). The authors'"'"' later papers were not checked.' || { echo FAILED 257; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 258 --by kb-claims_tracks --evidence 'gr-qc/0601112v1 L229-231: ds^2 = -(alpha^2 + a^2 beta^2) dt^2 + ..., alpha is the lapse; L591: static equation for alpha'"'"'/alpha.' || { echo FAILED 258; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 259 --by kb-claims_tracks --evidence 'gr-qc/0601112v1 L810-813: the first column reads 0.42, 0.045, 0.052, 0.77 in an otherwise increasing sequence; 0.45 and 0.52 are the only readings that keep it monotone [JUDGEMENT on the decimal shift]. Missing numbers 0.45, 0.52 are the corrected values.' || { echo FAILED 259; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 308 --by kb-claims_tracks --evidence '2108.11967v2 Table 1 (b=0.1) rows w0 = 0.6, 1.9, 3.2, 4.05150 at L492, L495, L498, L501. The 8e-5 agreement between two solvers is C'"'"'s own review result (review X2), not in the paper.' || { echo FAILED 308; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim verify 303 --by kb-claims_tracks --evidence 'The parser read the id 2105.05556 as a line number. 2105.05556v1 paper.tex: title (L75) reports stable configurations beyond the first binding-energy maximum; abstract (L88-89): evidence against the binding-energy hypothesis, stability at least up to the first maximum, multiple stability changes for some models, so the onset depends on the family. '"'"'No single literature value'"'"' is the track'"'"'s inference.' --locator '2105.05556v1:paper.tex:L75; 2105.05556v1:paper.tex:L88-89' || { echo FAILED 303; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/annotate.py annotate tracks/kb/claims_tracks/decisions/C1_annot.tsv || { echo FAILED annotate; fail=1; }
/usr/bin/python3 -I kb/bin/kb claim check --id 257 258 259 308 --by kb-claims_tracks || { echo FAILED check; fail=1; }
python3 -I tracks/kb/claims_tracks/scripts/ledger.py rows tracks/kb/claims_tracks/decisions/C1.tsv "$NRPIC_RUN_DIR/before.json" "$NRPIC_RUN_ID" > "$NRPIC_RUN_DIR/ledger_rows.tsv" || fail=1
exit $fail
